import { tags } from "typia";

import { IShoppingMallComplianceViolationSummary } from "./IShoppingMallComplianceViolationSummary";
import { IShoppingMallComplianceRecord } from "./IShoppingMallComplianceRecord";
import { IShoppingMallComplianceSystemStats } from "./IShoppingMallComplianceSystemStats";

/**
 * Comprehensive compliance report containing aggregated counts and summaries of
 * system logs and records for administrative audit and monitoring purposes.
 *
 * This report is generated by aggregating data across seven primary data
 * sources: shopping_mall_compliance_records (direct policy violations),
 * shopping_mall_audit_logs (administrative and critical system actions),
 * shopping_mall_payment_audit_logs (payment fraud detections),
 * shopping_mall_review_moderation_logs (review moderation actions),
 * shopping_mall_variant_audit_logs (product variant changes),
 * shopping_mall_config_history (system configuration changes), and
 * shopping_mall_seller_compliance_history (seller-specific violations).
 *
 * The data is presented in three major components:
 *
 * 1. High-level aggregate counts (total violations, most recent event)
 * 2. Detailed breakdown by violation category (payment fraud, review moderation,
 *    unauthorized changes, etc.)
 * 3. Specific examples of recent compliance issues
 *
 * The report is designed for administrative personnel only, providing the
 * insights needed to maintain platform integrity, support regulatory compliance
 * (SOC 2, GDPR, PCI-DSS), and respond to potential security concerns.
 * Administrators should use this report to identify patterns, prioritize
 * mitigation efforts, and ensure the platform maintains high ethical and legal
 * standards.
 *
 * All numeric fields represent counts based on actual database records.
 * Timestamps follow ISO 8601 format. The report is generative and not editable
 * - it provides an analytical view of system activity rather than interactive
 * functionality.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallComplianceReport = {
  /**
   * Total count of compliance records across all monitored entities.
   * Represents the overall volume of policy violations and interventions
   * logged by the platform's compliance monitoring system.
   *
   * This metric provides administrators with a high-level view of platform
   * integrity. High counts indicate potential systemic issues requiring
   * investigation, while low counts generally reflect good compliance
   * posture.
   *
   * The value is aggregated from multiple sources:
   * shopping_mall_compliance_records (direct violations),
   * shopping_mall_audit_logs (critical actions),
   * shopping_mall_payment_audit_logs (fraud detection triggers),
   * shopping_mall_review_moderation_logs (moderation actions),
   * shopping_mall_variant_audit_logs (inventory/price changes),
   * shopping_mall_config_history (configuration changes), and
   * shopping_mall_seller_compliance_history (seller-specific violations).
   */
  totalComplianceRecords: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Timestamp of the most recent compliance-related event across all
   * monitored systems.
   *
   * This field enables administrators to quickly assess the current state of
   * platform integrity. A very recent timestamp (within minutes) suggests
   * active compliance monitoring and recent enforcement actions, while an
   * older timestamp may indicate a period of system calm or potential
   * monitoring gaps.
   *
   * The value is derived from the latest timestamp among all
   * compliance-related tables: shopping_mall_compliance_records,
   * shopping_mall_audit_logs, shopping_mall_payment_audit_logs,
   * shopping_mall_review_moderation_logs, shopping_mall_variant_audit_logs,
   * shopping_mall_config_history, and
   * shopping_mall_seller_compliance_history.
   */
  lastComplianceEvent: string & tags.Format<"date-time">;

  /**
   * Breakdown of compliance violations by type, providing granular insight
   * into the nature and frequency of platform policy breaches.
   *
   * This object contains separate counters for each category of violation,
   * allowing administrators to identify patterns and prioritize remediation
   * efforts. The data is aggregated from associated database tables, with
   * each field representing a specific type of compliance issue.
   *
   * The fields in this object correspond to:
   *
   * - PaymentFraudAttempts: From shopping_mall_payment_audit_logs with fraud
   *   detection triggers
   * - ReviewModerationActions: From shopping_mall_review_moderation_logs with
   *   approval/rejection actions
   * - UnauthorizedChanges: From shopping_mall_variant_audit_logs with
   *   unauthorized attribute/inventory/price changes
   * - ConfigChanges: From shopping_mall_config_history with configuration
   *   modifications
   * - SellerViolations: From shopping_mall_seller_compliance_history with
   *   seller-specific violations
   * - OtherViolations: From shopping_mall_compliance_records with miscellaneous
   *   policy violations
   * - AuditLogEvents: From shopping_mall_audit_logs with critical system/admin
   *   actions
   */
  complianceViolationSummary: IShoppingMallComplianceViolationSummary;

  /**
   * List of the most recent individual compliance records that triggered
   * system flags or violations.
   *
   * This array contains summary details of recent compliance events from
   * shopping_mall_compliance_records, providing administrators with specific
   * examples to investigate. The list is limited to the most recent 10
   * records to avoid overwhelming the interface while providing actionable
   * insights.
   *
   * Each item in this array references the
   * IShoppingMallComplianceRecord.ISummary type and contains the minimum
   * information needed to identify and qualify each violation.
   *
   * The records in this list are sorted in descending order by eventTime,
   * with the most recent violation appearing first. Only records with status
   * 'active' or 'investigating' are included to focus on unresolved issues.
   */
  complianceRecordDetail: IShoppingMallComplianceRecord.ISummary[];

  /**
   * Timestamp indicating when this compliance report was generated by the
   * system.
   *
   * This field provides traceability and context for the report itself,
   * distinguishing between when compliance events occurred and when the
   * analytical report was produced. The timestamp is captured at the moment
   * of report generation, not when the underlying events occurred.
   *
   * The time comes from the system clock at the server and is generated
   * deterministically each time this endpoint is accessed. All values in the
   * report are synchronized to this generation timestamp for consistency.
   * Administrators use this field to understand the recency of the generated
   * report, especially important when investigating recent incidents where
   * eventTime and report generation time may differ significantly.
   */
  complianceReportGeneratedAt: string & tags.Format<"date-time">;

  /**
   * Technical statistics about the report generation process and underlying
   * system performance for operational monitoring.
   *
   * This object provides insight into the technical execution environment and
   * performance characteristics of the compliance reporting system.
   * Administrative teams can use this information for capacity planning,
   * system health monitoring, and performance optimization.
   *
   * The fields represent execution metrics from the reporting service:
   *
   * - ReportGenerationTime: Total milliseconds taken to compile the report from
   *   all data sources.
   * - DataSourcesQueried: Total number of database tables and collections
   *   accessed during report generation.
   * - DataPointsProcessed: Total number of individual records aggregated to
   *   produce the summary.
   * - ErrorsEncountered: Number of non-fatal errors during data extraction
   *   (e.g., temporary database timeout, partial data fetch).
   * - CacheHits: Number of previously computed report fragments served from
   *   cache.
   * - CacheMisses: Number of report fragments requiring fresh computation from
   *   source data.
   */
  systemStats: IShoppingMallComplianceSystemStats;
};
